                ptr = ptr->next;
            }
            ptr->next = new_node;
        }
    }
    return root;
}

// Frees all nodes in a process queue.
void helper_cleanup_process_queue(node **root) {
    if (root == NULL) {
        return;
    }
    node *current = *root;
    node *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *root = NULL;
}
